/* ========================================================================== */
/* BFUSION Portfolio Summary KPI — Modern 360°-style layout                  */
/* ========================================================================== */
/* Restored: variables the original stylesheet defined that are not
   part of the shared theme token set. */
/* Theme tokens. visual.ts pushes the resolved palette onto the root as CSS
   custom properties (src/theme.ts); the fallbacks below are the light preset,
   so a render with no tokens set matches the pre-theme visual.
   Brand accent stays fixed - it is suite chrome, not a themeable surface. */
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: auto;
  font-family: var(--psk-font-family, "Segoe UI"), wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: var(--bf-bg, #FFFFFF);
  position: relative;
  color: var(--bf-text, #242424);
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
.bfusion-psk {
  display: flex;
  flex-direction: column;
  padding-bottom: 24px;
  /* license badge clear-zone */
}
/* ========================================================================== */
/* Header bar (title + subtitle + info button)                                */
/* ========================================================================== */
.psk-header {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 10px 18px 8px 18px;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-bg, #FFFFFF);
  position: relative;
}
.psk-header__titles {
  flex: 1 1 auto;
  min-width: 0;
}
.psk-header__title {
  font-weight: 700;
  color: var(--bf-text, #242424);
  letter-spacing: 0.1px;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: var(--psk-header-title-font, 13px);
}
.psk-header__subtitle {
  margin-top: 2px;
  color: var(--bf-muted, #667079);
  font-weight: 400;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: var(--psk-header-subtitle-font, 10px);
}
.psk-header__info {
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-muted, #667079);
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  transition: all 0.15s ease;
  font-family: inherit;
  padding: 0;
}
.psk-header__info:hover {
  color: #fff;
  background: #E8612A;
  border-color: #E8612A;
  transform: scale(1.05);
  outline: none;
}
.psk-header__info:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 2px;
}
.psk-header__info-pop {
  position: absolute;
  top: calc(100% + 6px);
  right: 12px;
  z-index: 30;
  width: 320px;
  max-width: calc(100% - 24px);
  background: var(--bf-tile, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.12);
  padding: 12px 14px;
  color: var(--bf-text, #242424);
  line-height: 1.45;
  font-size: var(--psk-insight-font, 11px);
}
.psk-header__info-pop ul {
  margin: 8px 0 0 0;
  padding-left: 18px;
}
.psk-header__info-pop ul li {
  margin: 3px 0;
  color: var(--bf-muted, #667079);
}
.psk-info-pop__title {
  font-weight: 700;
  color: var(--bf-text, #242424);
  margin-bottom: 4px;
}
.psk-info-pop__desc {
  color: var(--bf-muted, #667079);
}
/* ========================================================================== */
/* Wrap                                                                       */
/* ========================================================================== */
.bfusion-kpi-wrap {
  width: 100%;
  padding: 14px 18px 4px 18px;
  display: block;
  background: var(--bf-bg, #FFFFFF);
}
.psk-row {
  margin-bottom: 14px;
}
.psk-row--primary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 10px;
}
/* ========================================================================== */
/* Modern KPI cards — top-band design                                         */
/* ========================================================================== */
.psk-card {
  --psk-card-color: var(--bf-strong, #1F2A44);
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 8px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow 0.2s ease, transform 0.15s ease;
  min-height: 120px;
}
.psk-card:hover {
  box-shadow: 0 4px 14px rgba(15, 23, 42, 0.08);
  transform: translateY(-1px);
}
.psk-card__band {
  background: var(--psk-card-color);
  color: #FFFFFF;
  padding: 8px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  min-height: 30px;
}
.psk-card__band-title {
  font-size: var(--psk-kpi-label-font, 11px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.psk-card__band-meta {
  font-size: var(--psk-card-band-meta-font, 10px);
  font-weight: 600;
  color: rgba(255, 255, 255, 0.85);
  white-space: nowrap;
}
.psk-card__body {
  padding: 12px 14px 12px 14px;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.psk-card__value {
  font-size: var(--psk-kpi-value-font, 28px);
  font-weight: 700;
  line-height: 1.1;
  color: var(--bf-text, #242424);
  font-variant-numeric: tabular-nums;
}
.psk-card__sub {
  font-size: var(--psk-kpi-subtitle-font, 11px);
  color: var(--bf-muted, #667079);
  line-height: 1.4;
}
.psk-card__pbar {
  margin-top: auto;
  height: 4px;
  background: var(--bf-surface-alt, #F1F5F9);
  border-radius: 2px;
  overflow: hidden;
}
.psk-card__pbar-fill {
  height: 100%;
  border-radius: 2px;
  background: var(--psk-card-color);
  transition: width 0.3s ease;
}
/* ========================================================================== */
/* Section panel — navy header band + body                                    */
/* ========================================================================== */
.psk-panel {
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 8px;
  overflow: hidden;
  margin-bottom: 14px;
}
.psk-panel__head {
  background: linear-gradient(90deg, var(--bf-surface-alt, #F4F5F7) 0%, var(--bf-surface-alt, #F4F5F7) 100%);
  color: var(--bf-text, #242424);
  padding: 10px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px solid var(--bf-rule, #E5E7EB);
}
.psk-panel__title {
  font-size: var(--psk-section-title-font, 12px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--bf-text, #242424);
}
.psk-panel__head-sub {
  font-size: var(--psk-panel-subtitle-font, 11px);
  color: var(--bf-muted, #667079);
  font-weight: 500;
  text-align: right;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 60%;
}
.psk-panel__body {
  padding: 14px 16px 16px 16px;
  background: var(--bf-bg, #FFFFFF);
}
/* ========================================================================== */
/* Financial panel layout                                                     */
/* ========================================================================== */
.psk-fin {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 18px;
  align-items: start;
}
.psk-fin__left {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.psk-fin__gauges {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  align-items: start;
  padding-top: 4px;
}
.psk-fin__col-title {
  font-size: var(--psk-column-title-font, 11px);
  color: var(--bf-muted, #667079);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 700;
  margin-bottom: 8px;
}
/* Horizontal bars (Budget / Actuals / Benefits) */
.psk-bars {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.psk-bars__row {
  display: grid;
  grid-template-columns: 70px 1fr auto;
  align-items: center;
  gap: 10px;
}
.psk-bars__label {
  font-size: var(--psk-bar-label-font, 11px);
  color: var(--bf-text, #242424);
  font-weight: 500;
}
.psk-bars__track {
  height: 14px;
  background: var(--bf-surface-alt, #F1F5F9);
  border-radius: 4px;
  overflow: hidden;
  position: relative;
}
.psk-bars__fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.4s ease;
}
.psk-bars__val {
  font-size: var(--psk-bar-value-font, 11px);
  color: var(--bf-text, #242424);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  min-width: 56px;
  text-align: right;
}
/* Donut / Half-gauge centerpiece */
.psk-fin__center {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 6px;
}
/* Stat tiles row */
.psk-stats {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 8px;
}
.psk-stat {
  background: var(--bf-surface, #F8F9FB);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 6px;
  padding: 10px 8px;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.psk-stat__val {
  font-size: var(--psk-stat-value-font, 20px);
  font-weight: 700;
  line-height: 1.1;
  font-variant-numeric: tabular-nums;
  color: var(--bf-text, #242424);
}
.psk-stat__label {
  font-size: var(--psk-stat-label-font, 11px);
  color: var(--bf-muted, #667079);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 600;
}
.psk-stat__caption {
  font-size: var(--psk-stat-caption-font, 10px);
  color: var(--bf-muted, #667079);
  margin-top: 2px;
}
/* Gauges (donut + half-gauge SVGs) */
.psk-gauge {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 4px;
}
.psk-gauge__label {
  font-size: var(--psk-gauge-label-font, 11px);
  font-weight: 600;
  color: var(--bf-muted, #667079);
  text-transform: uppercase;
  letter-spacing: 0.4px;
}
.psk-gauge__svg {
  width: 100%;
  max-width: 150px;
  height: auto;
  display: block;
}
.psk-gauge__svg--half {
  max-width: 170px;
}
.psk-gauge__subtitle {
  font-size: var(--psk-gauge-subtitle-font, 10px);
  color: var(--bf-muted, #667079);
  line-height: 1.3;
}
.psk-gauge__ring-bg {
  fill: none;
  stroke: var(--bf-surface-alt, #F1F5F9);
  stroke-width: 10;
}
.psk-gauge__ring-fg {
  fill: none;
  stroke-width: 10;
  stroke-linecap: round;
  transition: stroke-dashoffset 0.6s ease;
}
.psk-gauge__center {
  font-size: var(--psk-gauge-value-font, 22px);
  font-weight: 700;
  fill: var(--bf-text, #242424);
  text-anchor: middle;
  dominant-baseline: central;
  font-variant-numeric: tabular-nums;
}
.psk-gauge__tick {
  font-size: var(--psk-gauge-tick-font, 8px);
  fill: var(--bf-muted, #667079);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
/* ========================================================================== */
/* Health distribution panel                                                  */
/* ========================================================================== */
.psk-distrib {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.psk-distrib__bar {
  display: flex;
  height: 22px;
  border-radius: 6px;
  overflow: hidden;
  background: var(--bf-surface-alt, #F1F5F9);
  box-shadow: inset 0 0 0 1px rgba(15, 23, 42, 0.02);
}
.psk-seg {
  height: 100%;
  transition: width 0.4s ease;
  cursor: default;
}
.psk-seg:hover {
  opacity: 0.85;
}
.psk-distrib__legend {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}
.psk-legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--psk-legend-font, 11px);
  color: var(--bf-text, #242424);
  font-weight: 500;
}
.psk-legend-item strong {
  font-weight: 700;
  color: var(--bf-text, #242424);
  font-variant-numeric: tabular-nums;
}
.psk-legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}
/* ========================================================================== */
/* Health breakdown grid                                                      */
/* ========================================================================== */
.psk-breakdown__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 10px;
}
.psk-mini {
  background: var(--bf-surface, #F8F9FB);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 6px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.psk-mini__label {
  font-size: var(--psk-mini-label-font, 11px);
  font-weight: 700;
  color: var(--bf-text, #242424);
  text-transform: uppercase;
  letter-spacing: 0.4px;
}
.psk-mini__bar {
  display: flex;
  height: 8px;
  border-radius: 4px;
  overflow: hidden;
  background: var(--bf-surface-alt, #F1F5F9);
}
.psk-mini__counts {
  display: flex;
  justify-content: space-between;
  font-size: var(--psk-mini-count-font, 10px);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
/* ========================================================================== */
/* Responsive narrow                                                          */
/* ========================================================================== */
.bfusion-psk.psk-narrow .psk-fin {
  grid-template-columns: 1fr;
}
.bfusion-psk.psk-narrow .psk-fin__gauges {
  grid-template-columns: 1fr 1fr;
}
.bfusion-psk.psk-narrow .psk-stats {
  grid-template-columns: 1fr 1fr 1fr;
}
.bfusion-psk.psk-narrow .psk-row--primary {
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
}
.bfusion-psk.psk-medium .psk-fin {
  grid-template-columns: 1fr 1fr;
}
.bfusion-psk.psk-medium .psk-fin__gauges {
  grid-template-columns: 1fr 1fr;
}
/* ========================================================================== */
/* Landing Page                                                               */
/* ========================================================================== */
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: var(--bf-bg, #FFFFFF);
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #E8612A;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: var(--bf-text, #242424);
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: var(--bf-muted, #667079);
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: var(--bf-text, #242424);
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: var(--bf-rule, #E5E7EB);
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: var(--bf-muted, #667079);
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: var(--bf-muted, #667079);
}
/* ========================================================================== */
/* License Badge & Watermark                                                  */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: transparent;
  border: none;
  color: var(--bf-muted, #667079);
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
/* ========================================================================== */
/* Empty Data State                                                           */
/* ========================================================================== */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: var(--bf-muted, #667079);
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
